   226	    private BigDecimal calculateProductsSubtotal(List<OrderItem> items, Map<String, Product> products) {
   227	        BigDecimal subtotal = BigDecimal.ZERO;
   228	        for (OrderItem item : items) {
   229	            Product product = products.get(item.getSku());
   230	            BigDecimal itemTotal = product.getPrice()
   231	                    .multiply(new BigDecimal(item.getQuantity()))
   232	                    .setScale(2, RoundingMode.HALF_EVEN);
   233	            subtotal = subtotal.add(itemTotal);
   234	        }
   235	        return subtotal;
