   238	    private BigDecimal calculateTotalWeight(List<OrderItem> items, Map<String, Product> products) {
   239	        BigDecimal weight = BigDecimal.ZERO;
   240	        for (OrderItem item : items) {
   241	            Product product = products.get(item.getSku());
   242	            BigDecimal itemWeight = product.getWeightKg()
   243	                    .multiply(new BigDecimal(item.getQuantity()));
   244	            weight = weight.add(itemWeight);
   245	        }
   246	        return weight;
   247	    }
