   249	    private BigDecimal calculateInsurance(BigDecimal productsSubtotal, Region region) {
   250	        BigDecimal percentage = switch (region) {
   251	            case SOUTHEAST, SOUTH -> new BigDecimal("0.01");
   252	            case MIDWEST -> new BigDecimal("0.015");
   253	            case NORTH -> new BigDecimal("0.025");
   254	            case NORTHEAST -> new BigDecimal("0.02");
   255	        };
   256	
   257	        BigDecimal insurance = productsSubtotal.multiply(percentage)
   258	                .setScale(2, RoundingMode.HALF_EVEN);
   259	
   260	        BigDecimal limit = switch (region) {
   261	            case NORTH, NORTHEAST -> new BigDecimal("30.00");
   262	            case SOUTHEAST, SOUTH, MIDWEST -> null;
   263	        };
   264	
   265	        if (limit != null && insurance.compareTo(limit) > 0) {
   266	            return limit;
   267	        }
   268	
   269	        return insurance;
