    13	public class CouponService {
    14	
    15	    public BigDecimal calculateDiscount(CouponCode coupon, BigDecimal productsSubtotal,
    16	                                       BigDecimal shippingCost, List<OrderItem> items,
    17	                                       Map<String, Product> products, ShippingMethod shippingMethod,
    18	                                       boolean isFirstPurchase) {
    19	        BigDecimal discount = switch (coupon) {
    20	            case WELCOME10 -> {
    21	                if (!isFirstPurchase) {
    22	                    yield null;
    23	                }
    24	                yield productsSubtotal.multiply(new BigDecimal("0.10"))
    25	                        .setScale(2, RoundingMode.HALF_EVEN);
    26	            }
    27	            case MINUS50 -> {
    28	                if (productsSubtotal.compareTo(new BigDecimal("300.00")) < 0) {
    29	                    yield null;
    30	                }
    31	                yield new BigDecimal("50.00");
    32	            }
    33	            case FREESHIPPING -> {
    34	                if (shippingMethod == ShippingMethod.STORE_PICKUP) {
    35	                    yield null;
    36	                }
    37	                yield shippingCost;
    38	            }
    39	            case BUY3PAY2 -> calculateBuy3Pay2Discount(items, products);
    40	        };
    41	
    42	        if (discount == null) {
    43	            return null;
    44	        }
    45	
    46	        BigDecimal maxDiscount = productsSubtotal.multiply(new BigDecimal("0.30"))
    47	                .setScale(2, RoundingMode.HALF_EVEN);
    48	
    49	        if (discount.compareTo(maxDiscount) > 0) {
    50	            return maxDiscount;
    51	        }
    52	
    53	        return discount;
    54	    }
    55	
    56	    private BigDecimal calculateBuy3Pay2Discount(List<OrderItem> items, Map<String, Product> products) {
    57	        BigDecimal discount = BigDecimal.ZERO;
    58	
    59	        for (OrderItem item : items) {
    60	            if (item.getQuantity() >= 3) {
    61	                int freeUnits = item.getQuantity() / 3;
    62	                Product product = products.get(item.getSku());
    63	                BigDecimal itemDiscount = product.getPrice()
    64	                        .multiply(new BigDecimal(freeUnits))
    65	                        .setScale(2, RoundingMode.HALF_EVEN);
    66	                discount = discount.add(itemDiscount);
    67	            }
    68	        }
    69	
    70	        return discount;
    71	    }
