     6	import java.math.BigDecimal;
     7	import java.math.RoundingMode;
     8	
     9	public class PaymentService {
    10	
    11	    public static class PaymentCalculation {
    12	        public BigDecimal adjustment;
    13	        public BigDecimal finalTotal;
    14	        public int installments;
    15	        public BigDecimal installmentAmount;
    16	
    17	        public PaymentCalculation(BigDecimal adjustment, BigDecimal finalTotal,
    18	                                 int installments, BigDecimal installmentAmount) {
    19	            this.adjustment = adjustment;
    20	            this.finalTotal = finalTotal;
    21	            this.installments = installments;
    22	            this.installmentAmount = installmentAmount;
    23	        }
    24	    }
    25	
    26	    public PaymentCalculation calculatePayment(PaymentMethod method, BigDecimal orderTotal,
    27	                                              int installments, CouponCode coupon,
    28	                                              BigDecimal couponDiscount) {
    29	        return switch (method) {
    30	            case PIX -> calculatePix(orderTotal, coupon, couponDiscount);
    31	            case BANK_SLIP -> calculateBankSlip(orderTotal);
    32	            case CREDIT_CARD -> calculateCreditCard(orderTotal, installments);
    33	        };
    34	    }
    35	
    36	    private PaymentCalculation calculatePix(BigDecimal orderTotal, CouponCode coupon, BigDecimal couponDiscount) {
    37	        if (coupon != null && couponDiscount.compareTo(BigDecimal.ZERO) > 0) {
    38	            return new PaymentCalculation(BigDecimal.ZERO, orderTotal, 1, orderTotal);
    39	        }
    40	
    41	        BigDecimal discount = orderTotal.multiply(new BigDecimal("0.05"))
    42	                .setScale(2, RoundingMode.HALF_EVEN);
    43	        BigDecimal finalTotal = orderTotal.subtract(discount);
    44	
    45	        return new PaymentCalculation(discount.negate(), finalTotal, 1, finalTotal);
    46	    }
    47	
    48	    private PaymentCalculation calculateBankSlip(BigDecimal orderTotal) {
    49	        BigDecimal fee = new BigDecimal("3.49");
    50	        BigDecimal finalTotal = orderTotal.add(fee);
    51	
    52	        return new PaymentCalculation(fee, finalTotal, 1, finalTotal);
    53	    }
    54	
    55	    private PaymentCalculation calculateCreditCard(BigDecimal orderTotal, int installments) {
    56	        if (installments <= 3) {
    57	            BigDecimal installmentAmount = orderTotal.divide(new BigDecimal(installments), 2, RoundingMode.HALF_EVEN);
    58	            return new PaymentCalculation(BigDecimal.ZERO, orderTotal, installments, installmentAmount);
    59	        }
    60	
    61	        BigDecimal monthlyRate = new BigDecimal("0.0199");
    62	        BigDecimal onePlusRate = BigDecimal.ONE.add(monthlyRate);
    63	        BigDecimal denominator = BigDecimal.ONE.subtract(
    64	                onePlusRate.pow(-installments)
    65	        );
    66	
    67	        BigDecimal installmentAmount = orderTotal.multiply(monthlyRate)
    68	                .divide(denominator, 2, RoundingMode.HALF_EVEN);
    69	
    70	        BigDecimal finalTotal = installmentAmount.multiply(new BigDecimal(installments));
    71	        BigDecimal adjustment = finalTotal.subtract(orderTotal);
    72	
    73	        return new PaymentCalculation(adjustment, finalTotal, installments, installmentAmount);
    74	    }
    75	}
